import bisect
class Solution:
    def maximumCapacity(self, costs, capacity, budget):
        items = sorted(zip(costs, capacity))
        n = len(items)
        cs = [c for c, _ in items]
        pre = [0] * n
        for i, (_, cp) in enumerate(items):
            pre[i] = cp if i == 0 else max(pre[i - 1], cp)
        ans = 0
        for i in range(n):
            c, cp = items[i]
            if c < budget:
                ans = max(ans, cp)
            j = bisect.bisect_left(cs, budget - c, 0, i)
            if j > 0:
                ans = max(ans, cp + pre[j - 1])
        return ans

