class Solution {
    public int maximumCapacity(int[] costs, int[] capacity, int budget) {
        int n = costs.length;
        int[][] v = new int[n][2];
        for (int i = 0; i < n; i++) { v[i][0] = costs[i]; v[i][1] = capacity[i]; }
        Arrays.sort(v, (a, b) -> a[0] - b[0]);
        int[] cs = new int[n], pre = new int[n];
        for (int i = 0; i < n; i++) {
            cs[i] = v[i][0]; pre[i] = v[i][1];
            if (i > 0) pre[i] = Math.max(pre[i], pre[i - 1]);
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (v[i][0] < budget) ans = Math.max(ans, v[i][1]);
            int lo = 0, hi = i;
            while (lo < hi) { int m = (lo + hi) >>> 1; if (cs[m] < budget - v[i][0]) lo = m + 1; else hi = m; }
            if (lo > 0) ans = Math.max(ans, v[i][1] + pre[lo - 1]);
        }
        return ans;
    }
}

