var maximumCapacity = function(costs, capacity, budget) {
    const n = costs.length;
    const idx = [...Array(n).keys()].sort((a, b) => costs[a] - costs[b]);
    const cs = idx.map(i => costs[i]), pre = new Array(n);
    for (let i = 0; i < n; i++) pre[i] = Math.max(capacity[idx[i]], i ? pre[i - 1] : 0);
    let ans = 0;
    for (let i = 0; i < n; i++) {
        const c = cs[i], cp = capacity[idx[i]];
        if (c < budget) ans = Math.max(ans, cp);
        let lo = 0, hi = i;
        while (lo < hi) { const m = (lo + hi) >> 1; if (cs[m] < budget - c) lo = m + 1; else hi = m; }
        if (lo > 0) ans = Math.max(ans, cp + pre[lo - 1]);
    }
    return ans;
};
